assert_true(!str_contains($adminTableJs, '/firewall') && !str_contains($adminTableJs, '"firewall"'), 'Admin table should not expose the removed firewall screen share-link action.');
assert_true(!str_contains($adminAppJs, 'dashboard-screen-1'), 'Admin app should not expose dashboard screen 1 as a direct admin page.');
